import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        while (scanner.hasNext()) {
            String word = scanner.next();
            StringBuilder output = new StringBuilder();
            output.append(word.charAt(0));
            int changeFlag = 0;
            int pos = 1;
            while (pos < word.length()) {
                if (changeFlag == 0 && word.charAt(pos) == 'a' && pos + 1 < word.length() && word.charAt(pos + 1) == 't') {
                    output.append('@');
                    changeFlag = 1;
                    pos += 2;
                    continue;
                }
                if (pos + 2 < word.length() && word.charAt(pos) == 'd' && word.charAt(pos + 1) == 'o' && word.charAt(pos + 2) == 't') {
                    output.append('.');
                    pos += 3;
                    continue;
                }
                output.append(word.charAt(pos));
                pos++;
            }
            System.out.println(output.toString());
        }
        scanner.close();
    }
}
